// client/src/api/rouletteApi.js (수정)

// 🚨 axios 대신 인증 처리가 된 axiosInstance를 사용합니다.
import axiosInstance from './axiosInstance'; 

const API_URL = '/roulette'; 

// 🚨 getAuthHeaders 함수는 이제 필요 없습니다. axiosInstance가 토큰을 처리합니다.

/**
 * 룰렛 보상 목록을 가져옵니다. (GET /api/roulette/rewards)
 * 💡 이제 인증 헤더가 자동으로 포함됩니다.
 */
export const getRouletteRewards = async () => {
    // 💡 axiosInstance 사용
    try {
        const response = await axiosInstance.get(`${API_URL}/rewards`);
        // 서버가 { value: [...], Count } 형태로 반환할 수 있으므로 value가 있으면 value를 반환
        if (response.data && response.data.value) return response.data.value;
        return response.data;
    } catch (err) {
        // 네트워크/서버 오류 시에도 개발 편의를 위해 mock 데이터를 반환합니다.
        console.warn('getRouletteRewards failed, returning mock data:', err.message || err);
        return [
            { name: '50 포인트', type: 'POINTS', probability: 30 },
            { name: '100 포인트', type: 'POINTS', probability: 25 },
            { name: '200 포인트', type: 'POINTS', probability: 15 },
            { name: 'A 브랜드 10%', type: 'COUPON', probability: 10 },
            { name: 'B 브랜드 20%', type: 'COUPON', probability: 5 },
            { name: '500 포인트', type: 'POINTS', probability: 2 },
            { name: '꽝', type: 'NONE', probability: 13 },
        ];
    }
};

/**
 * 룰렛을 실행하고 보상을 받습니다. (POST /api/roulette/spin)
 */
export const spinRoulette = async () => {
    // 💡 axiosInstance 사용. 토큰 검증은 백엔드에 맡깁니다.
    const response = await axiosInstance.post(`${API_URL}/spin`, {});
    return response.data;
};
